//! Junction `<boundary>` and `<elevationGrid>`: the area of a junction and
//! the height of its ground.
//!
//! `tests/data/junction_areas.xodr` is generated by `junction_areas.py`.

use xodr::{load_file_with_provenance, JunctionArea, Warning};

const FIXTURE: &str = "tests/data/junction_areas.xodr";

fn areas() -> (Vec<JunctionArea>, Vec<Warning>) {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    (net.junction_areas().to_vec(), prov.warnings)
}

/// Twice the area a ring encloses in plan, positive counter-clockwise.
fn area(ring: &[xodr::Point]) -> f32 {
    ring.iter()
        .zip(ring.iter().cycle().skip(1))
        .map(|(a, b)| a.x * b.y - b.x * a.y)
        .sum::<f32>()
        / 2.0
}

#[test]
fn a_boundary_runs_counter_clockwise_round_its_segments_on_the_road_surface() {
    let (areas, _) = areas();
    let seven = &areas[0];
    assert_eq!(seven.od_id, "7");
    assert!(
        (area(&seven.boundary) - 70.0).abs() < 1e-3,
        "{}",
        area(&seven.boundary)
    );
    // Road 1 blends into the grid from x = 20, so the corners there stand
    // at its height, 0 m, and so does the grid at x = 30.
    let corners = [(20.0, -3.5), (30.0, -3.5), (30.0, 3.5), (20.0, 3.5)];
    for (x, y) in corners {
        assert!(
            seven
                .boundary
                .iter()
                .any(|p| (p.x - x).abs() < 1e-4 && (p.y - y).abs() < 1e-4 && p.z.abs() < 1e-4),
            "no corner at ({x}, {y})"
        );
    }
}

#[test]
fn the_grid_gives_its_heights_at_its_points_and_between_them() {
    let (areas, _) = areas();
    let seven = &areas[0];
    let at = |x, y| seven.height_at(x, y).unwrap();
    assert!((at(22.0, 0.0) - 0.2).abs() < 1e-9);
    assert!((at(26.0, 4.0)).abs() < 1e-9);
    // The cubic through the line's heights 0, 0.2, 0.2 and 0 rises between
    // the two middle ones: to 0.225 halfway, with slopes of 0.1 and -0.1.
    assert!((at(24.0, 0.0) - 0.225).abs() < 1e-9);
    let between = at(20.0, 0.0);
    assert!(between > 0.0 && between < 0.2, "{between}");
    assert!(seven.height_at(31.0, 0.0).is_none());
    assert!(seven.height_at(24.0, 4.5).is_none());
}

#[test]
fn the_mesh_covers_the_boundary_at_the_grids_height() {
    let (areas, _) = areas();
    let mesh = areas[0].mesh();
    mesh.validate().unwrap();
    let covered: f32 = mesh
        .indices
        .chunks_exact(3)
        .map(|t| {
            let [a, b, c] = [0, 1, 2].map(|k| mesh.vertices[t[k] as usize]);
            ((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)) / 2.0
        })
        .sum();
    assert!((covered - 70.0).abs() < 1e-2, "{covered}");
    let top = mesh.vertices.iter().map(|v| v.z).fold(0.0_f32, f32::max);
    assert!(top > 0.2 && top <= 0.225 + 1e-6, "{top}");
    assert!(mesh.normals.iter().all(|n| n.z > 0.9));
}

#[test]
fn the_roads_of_a_junction_stand_on_its_grid_past_the_transition() {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    let grid = &net.junction_areas()[0];
    let on_road_10: Vec<_> = prov.lanes.iter().filter(|p| p.road_id == "10").collect();
    assert_eq!(on_road_10.len(), 2);
    let mut top = 0.0_f32;
    for p in on_road_10 {
        let lane = net.lane(p.lane).unwrap();
        for point in lane.center.points().iter().filter(|p| p.x >= 22.0) {
            let want = grid.height_at(point.x.into(), point.y.into()).unwrap() as f32;
            assert!((point.z - want).abs() < 1e-4, "{point:?} not at {want}");
            top = top.max(point.z);
        }
    }
    assert!(top > 0.1, "the lanes rise over the grid's hump, to {top}");
    assert!(!prov
        .warnings
        .iter()
        .any(|w| w.to_string().contains("elevationGrid")));
}

#[test]
fn a_clockwise_boundary_with_a_segment_it_cannot_place_is_turned_and_warned_of() {
    let (areas, warnings) = areas();
    let eight = &areas[1];
    assert_eq!(eight.od_id, "8");
    assert!(area(&eight.boundary) > 0.0);
    assert!(eight.grid.is_none());
    let about_eight: Vec<String> = warnings
        .iter()
        .filter(|w| w.to_string().contains("junction \"8\""))
        .map(|w| w.to_string())
        .collect();
    assert_eq!(
        about_eight,
        [
            "junction \"8\": <boundary> segment on road \"99\" dropped",
            "junction \"8\": <boundary> segments leave a 10.00 m gap, joined straight",
            "junction \"8\": <boundary> runs clockwise, turned round",
        ]
    );
    let dropped = warnings
        .iter()
        .find(|w| matches!(w, Warning::BoundarySegmentDropped { .. }))
        .unwrap();
    assert_eq!(dropped.road_id(), "99");
}

/// Road 1 runs 20 m along +X with right lanes -1 and -2, 3.5 m each.
/// Junction 7's boundary is one joint across both, at road 1's end. Junction
/// 8's grid has no `<planView>`, and junction 9's is on an arc.
const ONE_SIDE: &str = r#"<OpenDRIVE>
  <road id="1" length="20" junction="-1">
    <planView><geometry s="0" x="0" y="0" hdg="0" length="20"><line/></geometry></planView>
    <lanes><laneSection s="0"><center><lane id="0" type="none"/></center><right>
      <lane id="-1" type="driving"><width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
      <lane id="-2" type="driving"><width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
    </right></laneSection></lanes>
  </road>
  <junction id="7">
    <boundary><segment type="joint" roadId="1" contactPoint="end" jointLaneStart="-2" jointLaneEnd="-1"/></boundary>
  </junction>
  <junction id="8">
    <elevationGrid sStart="0" gridSpacing="2"><elevation center="0"/><elevation center="0"/></elevationGrid>
  </junction>
  <junction id="9">
    <planView><geometry s="0" x="0" y="0" hdg="0" length="10"><arc curvature="0.2"/></geometry></planView>
    <elevationGrid sStart="0" gridSpacing="2"><elevation center="0"/><elevation center="0"/></elevationGrid>
  </junction>
</OpenDRIVE>"#;

#[test]
fn a_joint_across_two_lanes_on_one_side_crosses_both_whole() {
    let (net, _) = xodr::load_str_with_provenance(ONE_SIDE).unwrap();
    let area = net
        .junction_areas()
        .iter()
        .find(|a| a.od_id == "7")
        .unwrap();
    let ys: Vec<f32> = area.boundary.iter().map(|p| p.y).collect();
    assert_eq!(ys, [-7.0, -3.5, 0.0]);
}

#[test]
fn a_boundary_of_one_segment_is_not_closed() {
    let (_, prov) = xodr::load_str_with_provenance(ONE_SIDE).unwrap();
    assert!(prov.warnings.iter().any(|w| matches!(
        w,
        Warning::BoundaryNotClosed { junction_id, gap } if junction_id == "7" && (gap - 7.0).abs() < 1e-3
    )));
}

#[test]
fn a_grid_without_one_straight_reference_line_is_dropped_with_a_warning() {
    let (net, prov) = xodr::load_str_with_provenance(ONE_SIDE).unwrap();
    assert!(net.junction_areas().iter().all(|a| a.od_id == "7"));
    for id in ["8", "9"] {
        assert!(prov.warnings.contains(&Warning::ElevationGridDropped {
            junction_id: id.into()
        }));
    }
}

/// Rows of different widths: a point on the edge of a square the grid covers
/// whole gets its height, though the square beyond that edge is missing a
/// corner.
#[test]
fn a_point_on_the_edge_of_a_covered_square_has_a_height_on_ragged_rows() {
    let grid = xodr::ElevationGrid {
        origin: [0.0, 0.0],
        heading: 0.0,
        s_start: 0.0,
        spacing: 1.0,
        rows: vec![
            xodr::GridRow {
                center: 1.0,
                left: vec![2.0, 3.0],
                right: Vec::new(),
            },
            xodr::GridRow {
                center: 1.0,
                left: vec![2.0],
                right: Vec::new(),
            },
        ],
    };
    let at_edge = grid.height(0.5, 1.0).expect("on the covered square's edge");
    assert!((at_edge - 2.0).abs() < 1e-9, "{at_edge}");
    assert!(grid.height(0.5, 0.5).is_some(), "inside it");
}

#[test]
fn a_boundary_segment_off_its_road_is_dropped_with_a_warning() {
    let xodr = std::fs::read_to_string(FIXTURE).unwrap().replacen(
        r#"<segment type="lane" roadId="10" boundaryLane="-1" sStart="start" sEnd="end"/>"#,
        r#"<segment type="lane" roadId="10" boundaryLane="-1" sStart="start" sEnd="500"/>"#,
        1,
    );
    let (_, prov) = xodr::load_str_with_provenance(&xodr).unwrap();
    assert!(prov.warnings.contains(&Warning::BoundarySegmentDropped {
        junction_id: "7".into(),
        road_id: "10".into(),
    }));
}

#[test]
fn a_road_coming_in_blends_into_the_grid_over_its_transition_length() {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    let grid = &net.junction_areas()[0];
    let lane = prov
        .lanes
        .iter()
        .find(|p| p.road_id == "10" && p.od_id == -1)
        .unwrap();
    let points = net.lane(lane.lane).unwrap().center.points();
    let at_x = |x: f32| {
        points
            .iter()
            .min_by(|a, b| (a.x - x).abs().total_cmp(&(b.x - x).abs()))
            .copied()
            .unwrap()
    };
    let start = at_x(20.0);
    assert!(
        start.z.abs() < 1e-4,
        "it starts at road 1's height: {start:?}"
    );
    let grid_z = |p: xodr::Point| grid.height_at(p.x.into(), p.y.into()).unwrap() as f32;
    assert!(grid_z(start) > 0.05, "the grid would have stepped up there");
    for p in points.iter().filter(|p| p.x >= 22.0) {
        assert!(
            (p.z - grid_z(*p)).abs() < 1e-4,
            "{p:?} is past the zone, on the grid"
        );
    }
    let inside: Vec<_> = points.iter().filter(|p| p.x > 20.0 && p.x < 22.0).collect();
    assert!(!inside.is_empty());
    assert!(
        inside.windows(2).all(|w| w[1].z >= w[0].z - 1e-5),
        "it rises smoothly"
    );
}

#[test]
fn a_transition_without_lane_segments_beside_it_is_dropped_with_a_warning() {
    let xodr = std::fs::read_to_string(FIXTURE).unwrap().replace(
        r#"<segment type="lane" roadId="10" boundaryLane="1" sStart="end" sEnd="start"/><segment type="joint" roadId="1""#,
        r#"<segment type="joint" roadId="1""#,
    );
    let (_, prov) = xodr::load_str_with_provenance(&xodr).unwrap();
    assert!(prov.warnings.contains(&Warning::TransitionDropped {
        junction_id: "7".into(),
        road_id: "1".into(),
    }));
}

#[test]
fn a_transition_at_a_numbered_contact_point_blends_from_that_end() {
    let sloped = std::fs::read_to_string(FIXTURE).unwrap().replace(
        r#"<planView><geometry s="0" x="0" y="0" hdg="0" length="20"><line/></geometry></planView>"#,
        r#"<planView><geometry s="0" x="0" y="0" hdg="0" length="20"><line/></geometry></planView>
        <elevationProfile><elevation s="0" a="-1" b="0.05" c="0" d="0"/></elevationProfile>"#,
    );
    let joint = r#"roadId="1" contactPoint="end" jointLaneStart="1" jointLaneEnd="-1" transitionLength="2"/></boundary>
    <elevationGrid"#;
    assert!(sloped.contains(joint));
    let numbered = sloped.replace(joint, &joint.replace(r#""end""#, r#""20""#));
    let lane = |xml: &str| {
        let (net, prov) = xodr::load_str_with_provenance(xml).unwrap();
        let at = prov
            .lanes
            .iter()
            .find(|p| p.road_id == "10" && p.od_id == -1)
            .unwrap();
        net.lane(at.lane).unwrap().center.points().to_vec()
    };
    assert_eq!(lane(&numbered), lane(&sloped));
}

/// The plan length of the edges of `mesh` that only one triangle has,
/// vertices matched to 0.1 mm in 3D.
fn open_length(mesh: &xodr::Mesh) -> f32 {
    use std::collections::HashMap;
    let key = |p: xodr::Point| [p.x, p.y, p.z].map(|c| (c * 1e4).round() as i64);
    let mut edges: HashMap<_, (usize, f32)> = HashMap::new();
    for t in mesh.indices.chunks_exact(3) {
        for (a, b) in [(t[0], t[1]), (t[1], t[2]), (t[2], t[0])] {
            let (p, q) = (mesh.vertices[a as usize], mesh.vertices[b as usize]);
            let (ka, kb) = (key(p), key(q));
            let length = (p.x - q.x).hypot(p.y - q.y);
            edges
                .entry((ka.min(kb), ka.max(kb)))
                .or_insert((0, length))
                .0 += 1;
        }
    }
    edges
        .values()
        .filter(|(n, _)| *n == 1)
        .map(|(_, l)| l)
        .sum()
}

#[test]
fn the_ground_of_a_junction_covers_it_with_no_cracks_between_its_triangles() {
    let net = xodr::load_file("tests/data/city.xodr").unwrap();
    for area in net.junction_areas().iter().filter(|a| a.grid.is_some()) {
        let ring = &area.boundary;
        let mesh = area.mesh();
        let twice =
            |[a, b, c]: [xodr::Point; 3]| (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
        let inside: f32 = (1..ring.len() - 1)
            .map(|k| twice([ring[0], ring[k], ring[k + 1]]))
            .sum::<f32>()
            / 2.0;
        let covered: f32 = mesh
            .indices
            .chunks_exact(3)
            .map(|t| twice([0, 1, 2].map(|k| mesh.vertices[t[k] as usize])))
            .sum::<f32>()
            / 2.0;
        assert!(
            (covered - inside).abs() < 1e-3 * inside,
            "junction {}: {covered} m² of {inside}",
            area.od_id
        );
        let perimeter: f32 = (0..ring.len())
            .map(|k| {
                let (p, q) = (ring[k], ring[(k + 1) % ring.len()]);
                (p.x - q.x).hypot(p.y - q.y)
            })
            .sum();
        let open = open_length(&mesh);
        assert!(
            (open - perimeter).abs() < 1e-2 * perimeter,
            "junction {}: {open} m of open edges round a {perimeter} m boundary",
            area.od_id
        );
    }
}
